const item = $('Slack Trigger').first().json;
const text = item.text || "";
const channel = item.channel || "";
const ts = item.ts || "";
const team = item.team || "";

// thread_ts 存在 = thread 里 mention；不存在 = 新对话
const sessionId = item.thread_ts || ts;

// 构造 Slack thread 链接，方便 agent 读取上下文
const tsForLink = ts.replace(".", "");
const threadLink = team && channel && ts
  ? `https://app.slack.com/client/${team}/${channel}/thread/${channel}-${tsForLink}`
  : "";

// 组装 prompt：原始文本 + thread 链接
let chatInput = `> 注意这是来自 thread 的用户，请务必在需要回复/反馈/同步进度时，调用 Slack 工具进行回复（回复需遵循 mrkdwn 格式而不是 markdown 格式）\n` + text;
if (threadLink) {
  chatInput += `\n\n[Slack Thread](${threadLink})`;
}

return [{ json: { chatInput, channel, user: item.user, ts, threadLink, sessionId } }];

